import{_ as e,c as t,o as r,a as o}from"./app.9a45957d.js";const m=JSON.parse('{"title":"How to use ReplyBridge — day-to-day tips","description":"Use keywords, automation timing, and messages that match how you actually run your Instagram—written for creators and marketers, not developers.","frontmatter":{"title":"How to use ReplyBridge — day-to-day tips","description":"Use keywords, automation timing, and messages that match how you actually run your Instagram—written for creators and marketers, not developers."},"headers":[{"level":2,"title":"The usual flow","slug":"the-usual-flow","link":"#the-usual-flow","children":[]},{"level":2,"title":"Auto DM vs public reply","slug":"auto-dm-vs-public-reply","link":"#auto-dm-vs-public-reply","children":[]},{"level":2,"title":"Keywords & “once per person”","slug":"keywords-once-per-person","link":"#keywords-once-per-person","children":[]},{"level":2,"title":"Automation “until when?”","slug":"automation-until-when","link":"#automation-until-when","children":[]},{"level":2,"title":"Quick checks","slug":"quick-checks","link":"#quick-checks","children":[]},{"level":2,"title":"Learn more for your own Instagram","slug":"learn-more-for-your-own-instagram","link":"#learn-more-for-your-own-instagram","children":[]}],"relativePath":"replybridge/usage.md"}'),n={name:"replybridge/usage.md"},s=o('<h1 id="how-to-use-replybridge" tabindex="-1">How to use ReplyBridge <a class="header-anchor" href="#how-to-use-replybridge" aria-hidden="true">#</a></h1><p>After <strong><a href="/replybridge/getting-started">installing and connecting Instagram</a></strong>, you manage everything <strong>inside the app</strong>: pick posts, write messages, and choose when automation should run.</p><hr><h2 id="the-usual-flow" tabindex="-1">The usual flow <a class="header-anchor" href="#the-usual-flow" aria-hidden="true">#</a></h2><ol><li>Open your <strong>list of posts</strong> in ReplyBridge.</li><li><strong>Choose one post</strong> to start (you can add more later).</li><li>Turn on automation and fill in: <ul><li><strong>DM text</strong> — what people receive in private messages.</li><li><strong>Optional public reply</strong> — what everyone sees under the comment.</li><li><strong>Optional keywords</strong> — only answer comments that contain certain words.</li></ul></li><li>Set <strong>how long</strong> automation stays on (great for sales or events).</li><li>Save. New comments on that post can trigger your messages <strong>automatically</strong>.</li></ol><hr><h2 id="auto-dm-vs-public-reply" tabindex="-1">Auto DM vs public reply <a class="header-anchor" href="#auto-dm-vs-public-reply" aria-hidden="true">#</a></h2><table><thead><tr><th></th><th>Best for…</th></tr></thead><tbody><tr><td><strong>Auto DM</strong></td><td>Links, coupons, “DM us this word”, personal next steps—<strong>private</strong>.</td></tr><tr><td><strong>Public reply</strong></td><td>Short FAQs everyone should see—<strong>visible on the post</strong>.</td></tr></tbody></table><p>You can use <strong>both</strong>, <strong>one</strong>, or switch them per post.</p><hr><h2 id="keywords-once-per-person" tabindex="-1">Keywords &amp; “once per person” <a class="header-anchor" href="#keywords-once-per-person" aria-hidden="true">#</a></h2><ul><li><strong>Keywords</strong> — Example: only send a DM if the comment includes “info” or “price”. Reduces noise and spammy replies.</li><li><strong>Once per person</strong> — Sends your DM only <strong>once</strong> to the same person on that post—useful for giveaways or collecting leads fairly.</li></ul><hr><h2 id="automation-until-when" tabindex="-1">Automation “until when?” <a class="header-anchor" href="#automation-until-when" aria-hidden="true">#</a></h2><p>Your DM and public reply can share <strong>one end date</strong>. When the time is up, automation stops—so you don’t accidentally keep promoting an old sale.</p><hr><h2 id="quick-checks" tabindex="-1">Quick checks <a class="header-anchor" href="#quick-checks" aria-hidden="true">#</a></h2><ul><li>Wrong post selected? Open that post in ReplyBridge and adjust settings.</li><li>No DM arrived? Check keywords, time limit, and that Instagram is still connected.</li><li>Too many DMs? Tighten keywords or turn on “once per person.”</li></ul><hr><h2 id="learn-more-for-your-own-instagram" tabindex="-1">Learn more for your own Instagram <a class="header-anchor" href="#learn-more-for-your-own-instagram" aria-hidden="true">#</a></h2><p>Ideas for posts, Reels, and Stories: <strong><a href="/replybridge/marketing/">Marketing &amp; tips</a></strong></p><p>Step-by-step from zero: <strong><a href="/replybridge/getting-started">Get started</a></strong></p>',22),a=[s];function i(l,d,h,u,c,p){return r(),t("div",null,a)}const y=e(n,[["render",i]]);export{m as __pageData,y as default};
